	private static void collectBoundNames(Node node, Set<String> candidateNames, Set<String> names) {
		if (node instanceof ASTVar variable && candidateNames.contains(variable.getName())) {
			names.add(variable.getName());
		}
		for (int i = 0; i < node.jjtGetNumChildren(); i++) {
			collectBoundNames(node.jjtGetChild(i), candidateNames, names);
		}
	}

	private static void collectBoundNames(Node node, BindingSet bindings, Set<String> names) {
		if (node instanceof ASTVar variable && bindings.hasBinding(variable.getName())) {
			names.add(variable.getName());
		}
		for (int i = 0; i < node.jjtGetNumChildren(); i++) {
			collectBoundNames(node.jjtGetChild(i), bindings, names);
		}
	}

	private static void checkBindingScope(Node node, ASTQuery root, Set<String> names, Set<String> groupBindings,
			Map<Node, Set<String>> assurance, int groupDepth, boolean correlated) {
		if ((node instanceof ASTQuery && node != root || node instanceof ASTServiceGraphPattern)
				&& containsName(node, names)) {
			throw unsupportedBindings("nested query or SERVICE scope");
		}
		if (node instanceof ASTLateralGraphPattern && containsName(node, names)) {
			throw unsupportedBindings("LATERAL input scope");
		}
		if (node instanceof ASTExistsFunc || node instanceof ASTNotExistsFunc) {
			correlated = true;
		}
		if (node instanceof ASTGraphPatternGroup) {
			Set<String> localBindings = assuredBindings(node, assurance);
			Set<String> preceding = new LinkedHashSet<>();
			for (int i = 0; i < node.jjtGetNumChildren(); i++) {
				Node child = node.jjtGetChild(i);
				if (child instanceof ASTMinusGraphPattern
						&& hasUnassuredName(child, names, preceding)) {
					throw unsupportedBindings("MINUS right-hand input changes solution domains");
				}
				checkBindingScope(child, root, names, localBindings, assurance, groupDepth + 1, correlated);
				preceding.addAll(assuredBindings(child, assurance));
			}
			return;
		}
		if (!correlated && groupDepth > 1 && (node instanceof ASTConstraint || node instanceof ASTBind)
				&& hasUnassuredName(node, names, groupBindings)) {
			throw unsupportedBindings("nested FILTER or BIND input scope");
		}
		if (node instanceof ASTGroupCondition && hasUnassuredName(node, names, groupBindings)) {
			throw unsupportedBindings("GROUP BY binding without an assured query value");
		}
		if (node instanceof ASTSelectQuery select && select == root) {
			if (select.getGroupClause() != null
					&& hasUnassuredName(select.getGroupClause(), names, groupBindings)) {
				throw unsupportedBindings("GROUP BY binding without an assured query value");
			}
			if (select.getSelect().isWildcard() && !groupBindings.containsAll(names)) {
				throw unsupportedBindings("SELECT * would expose an additional input binding");
			}
			for (int i = 0; i < select.getSelect().jjtGetNumChildren(); i++) {
				Node projection = select.getSelect().jjtGetChild(i);
				if (projection instanceof ASTProjectionElem element && !element.hasAlias()
						&& hasUnassuredName(element, names, groupBindings)) {
					throw unsupportedBindings(
							"OPTIONAL or unbound projection would expose an additional input binding");
				}
			}
		}
		if (node instanceof ASTProjectionElem projection && names.contains(projection.getAlias())) {
			throw unsupportedBindings("projection target");
		}
		if (node instanceof ASTBind || node instanceof ASTGroupCondition && node.jjtGetNumChildren() > 1) {
			Node target = node.jjtGetChild(node.jjtGetNumChildren() - 1);
			if (target instanceof ASTVar variable && names.contains(variable.getName())) {
				throw unsupportedBindings("assignment target");
			}
		}
		for (int i = 0; i < node.jjtGetNumChildren(); i++) {
			checkBindingScope(node.jjtGetChild(i), root, names, groupBindings, assurance, groupDepth, correlated);
		}
	}

	private static boolean hasUnassuredName(Node node, Set<String> names, Set<String> assured) {
		if (node instanceof ASTVar variable && names.contains(variable.getName())
				&& !assured.contains(variable.getName())) {
			return true;
		}
		for (int i = 0; i < node.jjtGetNumChildren(); i++) {
			if (hasUnassuredName(node.jjtGetChild(i), names, assured)) {
				return true;
			}
		}
		return false;
	}

	/** Names produced by every successful mapping, excluding optional, negative and expression-only domains. */
	private static Set<String> assuredBindings(Node node, Map<Node, Set<String>> assurance) {
		if (node != null && assurance.containsKey(node)) {
			return assurance.get(node);
		}
		Set<String> names = new LinkedHashSet<>();
		if (node != null) {
			assurance.put(node, names);
		}
		if (node == null || node instanceof ASTOptionalGraphPattern || node instanceof ASTMinusGraphPattern
				|| node instanceof ASTConstraint || node instanceof ASTBind || node instanceof ASTQuery
				|| node instanceof ASTExistsFunc || node instanceof ASTNotExistsFunc) {
			return names;
		}
		if (node instanceof ASTTriplesSameSubject || node instanceof ASTTriplesSameSubjectPath) {
			collectNames(node, names);
			return names;
		}
		if (node instanceof ASTBindingsClause || node instanceof ASTInlineData) {
			if (containsType(node, ASTBindingSet.class) && !containsUndefinedBinding(node)) {
				collectNames(node, names);
			}
			return names;
		}
		if (node instanceof ASTUnionGraphPattern) {
			for (int i = 0; i < node.jjtGetNumChildren(); i++) {
				Set<String> branch = assuredBindings(node.jjtGetChild(i), assurance);
				if (i == 0) {
					names.addAll(branch);
				} else {
					names.retainAll(branch);
				}
			}
			return names;
		}
		if (node instanceof ASTGraphGraphPattern && node.jjtGetChild(0) instanceof ASTVar graph) {
			names.add(graph.getName());
		}
		for (int i = 0; i < node.jjtGetNumChildren(); i++) {
			names.addAll(assuredBindings(node.jjtGetChild(i), assurance));
		}
		return names;
	}

	private static void collectNames(Node node, Set<String> names) {
		if (node instanceof ASTVar variable) {
			names.add(variable.getName());
		}
		for (int i = 0; i < node.jjtGetNumChildren(); i++) {
			collectNames(node.jjtGetChild(i), names);
		}
	}

	private static boolean containsType(Node node, Class<? extends Node> type) {
		if (type.isInstance(node)) {
			return true;
		}
		for (int i = 0; i < node.jjtGetNumChildren(); i++) {
			if (containsType(node.jjtGetChild(i), type)) {
				return true;
			}
		}
		return false;
	}

	private static boolean containsUndefinedBinding(Node node) {
		if (node instanceof ASTBindingValue && node.jjtGetNumChildren() == 0) {
			return true;
		}
		for (int i = 0; i < node.jjtGetNumChildren(); i++) {
			if (containsUndefinedBinding(node.jjtGetChild(i))) {
				return true;
			}
		}
		return false;
	}

	private static boolean containsName(Node node, Set<String> names) {
		if (node instanceof ASTVar variable && names.contains(variable.getName())) {
			return true;
		}
		for (int i = 0; i < node.jjtGetNumChildren(); i++) {
			if (containsName(node.jjtGetChild(i), names)) {
				return true;
			}
		}
		return false;
	}

	private static UnsupportedOperationException unsupportedBindings(String shape) {
		return new UnsupportedOperationException("Unsupported initial-binding transport: " + shape);
	}

	private static void appendBindingValue(Value value, StringBuilder result) {
		if (value instanceof RemoteBNode) {
			throw unsupportedBindings("remote blank node requires a verified canonical mapping");
		} else if (value instanceof BNode blank) {
			result.append(BlankNodeReferences.toReference(blank.getID()));
		} else if (value instanceof IRI iri) {
			appendBindingIRI(iri, result);
		} else if (value instanceof Literal literal) {
			result.append('"').append(escape(literal.getLabel())).append('"');
			if (literal.getLanguage().isPresent()) {
				result.append('@').append(literal.getLanguage().get());
				if (literal.getBaseDirection() != Literal.BaseDirection.NONE) {
					result.append("--").append(literal.getBaseDirection().name().toLowerCase(Locale.ROOT));
				}
			} else {
				result.append("^^");
				appendBindingIRI(literal.getDatatype(), result);
			}
		} else if (value instanceof TripleTerm triple) {
			result.append("<<( ");
			appendBindingValue(triple.getSubject(), result);
			result.append(' ');
			appendBindingValue(triple.getPredicate(), result);
			result.append(' ');
			appendBindingValue(triple.getObject(), result);
			result.append(" )>>");
		} else {
			throw unsupportedBindings("unsupported RDF value " + value);
		}
	}

	private static void appendBindingIRI(IRI iri, StringBuilder result) {
		if (iri.stringValue().startsWith("_:")) {
			throw unsupportedBindings("IRI spelling reserved for blank-node references");
		}
		result.append(BlankNodeReferences.toIRIRef(iri.stringValue()));
	}

	/**
	 * Creates a string representing of the supplied {@link Namespace namespaces} as SPARQL prefix declarations. This
	 * can be used when composing a SPARQL query string in code, for example:
	 *
	 * <pre>
	 * <code>
	 * String query = SPARQLQueries.getPrefixClauses(connection.getNamespaces()) + "SELECT * WHERE { ?s ex:myprop ?o }";
	 * </code>
	 * </pre>
	 *
	 * @param namespaces one or more {@link Namespace} objects.
	 * @return one or more SPARQL prefix declarations (each separated by a newline), as a String.
	 * @since 3.6.0
	 */
	public static String getPrefixClauses(Iterable<Namespace> namespaces) {
		final StringBuilder sb = new StringBuilder();
		for (Namespace namespace : namespaces) {
			sb.append(String.format("PREFIX %s: <%s>\n", namespace.getPrefix(), namespace.getName()));
		}
		return sb.toString();
	}

	/**
	 * Escape the supplied string with backslashes for any special characters, so it can be used as a string literal
	 * value in a SPARQL query.
	 *
	 * @see <a href="https://www.w3.org/TR/sparql11-query/#grammarEscapes">SPAQL 1.1 grammar escapes</a>
	 * @since 3.6.0
	 */
	public static String escape(String s) {
		s = s.replace("\\", "\\\\");
		s = s.replace("\t", "\\t");
		s = s.replace("\n", "\\n");
		s = s.replace("\r", "\\r");
		s = s.replace("\b", "\\b");
		s = s.replace("\f", "\\f");
		s = s.replace("\"", "\\\"");
		s = s.replace("'", "\\'");
		return s;
	}

	/**
	 * Un-escapes a backslash-escaped SPARQL literal value string. Any recognized \-escape sequences are substituted
	 * with their un-escaped value.
	 *
	 * @param s An SPARQL literal string with backslash escapes.
	 * @return The un-escaped string.
	 * @throws IllegalArgumentException If the supplied string is not a correctly escaped SPARQL string.
	 * @see <a href="https://www.w3.org/TR/sparql11-query/#grammarEscapes">SPAQL 1.1 grammar escapes</a>
	 * @since 3.6.0
	 */
	public static String unescape(String s) {
		int backSlashIdx = s.indexOf('\\');

		if (backSlashIdx == -1) {
			// No escaped characters found
			return s;
		}

		int startIdx = 0;
		int sLength = s.length();
		StringBuilder sb = new StringBuilder(sLength);

		while (backSlashIdx != -1) {
			sb.append(s, startIdx, backSlashIdx);

			if (backSlashIdx + 1 >= sLength) {
				throw new IllegalArgumentException("Unescaped backslash in: " + s);
			}

			char c = s.charAt(backSlashIdx + 1);
			switch (c) {
			case 't':
				sb.append('\t');
				startIdx = backSlashIdx + 2;
				break;
			case 'n':
				sb.append('\n');
				startIdx = backSlashIdx + 2;
				break;
			case 'r':
				sb.append('\r');
				startIdx = backSlashIdx + 2;
				break;
			case 'b':
				sb.append('\b');
				startIdx = backSlashIdx + 2;
				break;
			case 'f':
				sb.append('\f');
				startIdx = backSlashIdx + 2;
				break;
			case '"':
				sb.append('"');
				startIdx = backSlashIdx + 2;
				break;
			case '\'':
				sb.append('\'');
				startIdx = backSlashIdx + 2;
				break;
			case '\\':
				sb.append('\\');
				startIdx = backSlashIdx + 2;
				break;
			default:
				throw new IllegalArgumentException("Unescaped backslash in: " + s);
			}

			backSlashIdx = s.indexOf('\\', startIdx);
		}

		sb.append(s.substring(startIdx));

		return sb.toString();
	}
